{"path":"/workspace/codebase/rust/src/main.rs","command":"create","file_text":"//! jscodeshift CLI — Rust migration of the Facebook jscodeshift toolkit runner.
//!
//! Transform execution (user codemods, Collection API, recast/babel parsers)
//! remains in a minimal Node.js compatibility bridge. Everything else — CLI,
//! argument parsing, file discovery, ignore rules, worker orchestration, and
//! reporting — lives here.

mod args;
mod color;
mod ignore;
mod runner;
mod version;

use std::io::{self, Read};
use std::path::PathBuf;
use std::process;

use args::{ParseError, Parser};
use runner::RunOptions;

fn main() {
    if let Err(code) = real_main() {
        process::exit(code);
    }
}

fn real_main() -> Result<(), i32> {
    let parser = args::build_cli_parser();
    let (options, positional) = match parser.parse(std::env::args().skip(1).collect()) {
        Ok(v) => v,
        Err(ParseError {
            message,
            exit_code,
        }) => {
            let out: &mut dyn io::Write = if exit_code == 0 {
                &mut io::stdout()
            } else {
                &mut io::stderr()
            };
            let _ = write!(out, "{}", message);
            return Err(exit_code);
        }
    };

    if positional.is_empty() && !options.stdin {
        let msg = format!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            parser.help_text()
        );
        eprint!("{}", msg);
        return Err(1);
    }

    let paths: Vec<String> = if options.stdin {
        let mut buffer = String::new();
        io::stdin()
            .read_to_string(&mut buffer)
            .map_err(|_| 1)?;
        buffer
            .split('\n')
            .map(|s| s.to_string())
            .filter(|s| !s.is_empty() || true) // preserve empty lines like JS split
            .collect()
    } else {
        positional
    };

    // Mirror JS: empty trailing line from split creates empty string path — filter blanks for safety
    // actually JS does buffer.split('\n') and passes all including possible trailing "".
    // getAllFiles skips non-existing paths with a message. Keep same.

    let transform = if options.transform.starts_with("http://")
        || options.transform.starts_with("https://")
    {
        options.transform.clone()
    } else {
        PathBuf::from(&options.transform)
            .canonicalize()
            .unwrap_or_else(|_| {
                // If it doesn't exist yet, still resolve relative to cwd like path.resolve
                std::env::current_dir()
                    .unwrap_or_else(|_| PathBuf::from("."))
                    .join(&options.transform)
            })
            .to_string_lossy()
            .to_string()
    };

    let run_opts = RunOptions {
        transform_file: transform,
        paths,
        cpus: options.cpus,
        verbose: options.verbose,
        dry: options.dry,
        print: options.print,
        babel: options.babel,
        extensions: options.extensions.clone(),
        ignore_pattern: options.ignore_pattern.clone(),
        ignore_config: options.ignore_config.clone(),
        gitignore: options.gitignore,
        run_in_band: options.run_in_band,
        silent: options.silent,
        parser: options.parser.clone(),
        parser_config: options.parser_config.clone(),
        fail_on_error: options.fail_on_error,
        // Forward unknown / custom options as JSON object for the transform
        extra: options.extra.clone(),
    };

    match runner::run(run_opts) {
        Ok(stats) => {
            if options.fail_on_error && stats.error > 0 {
                return Err(1);
            }
            Ok(())
        }
        Err(e) => {
            eprintln!("{}", e);
            Err(1)
        }
    }
