#[derive(Debug, Clone)]
pub struct ParseError {
    pub message: String,
    pub exit_code: i32,
}

#[derive(Debug, Clone)]
pub struct CliOptions {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: i32,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: String,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<Value>,
    pub fail_on_error: bool,
    pub stdin: bool,
    /// All parsed options as JSON (including unknowns) forwarded to transforms.
    pub extra: Map<String, Value>,
}

#[derive(Clone)]
struct OptionDef {
    key: String,
    full: String,
    abbr: Option<String>,
    flag: bool,
    list: bool,
    default: Option<Value>,
    default_help: Option<String>,
    choices: Option<Vec<Value>>,
    help: Option<String>,
    metavar: Option<String>,
    display_index: i32,
    /// Special processing: "number", "parser_config", "version"
    process: Option<&'static str>,
    callback: Option<&'static str>,
}

pub struct Parser {
    defs: Vec<OptionDef>,
    by_flag: HashMap<String, usize>,
}

impl Parser {
    pub fn help_text(&self) -> String {
        get_help_text(&self.defs)
    }

    pub fn parse(&self, args: Vec<String>) -> Result<(CliOptions, Vec<String>), ParseError> {
        parse_args(&self.defs, &self.by_flag, args)
    }
}

