fn default_extensions_string() -> String {
    // Mirrors @babel/core DEFAULT_EXTENSIONS + ts,tsx sorted
    let mut exts = vec![
        "js", "jsx", "es6", "es", "mjs", "cjs", "ts", "tsx",
    ];
    // DEFAULT_EXTENSIONS order from babel then ts/tsx then sort
    // babel: .js, .jsx, .es6, .es, .mjs, .cjs
    exts = vec!["cjs", "es", "es6", "js", "jsx", "mjs", "ts", "tsx"]
        .into_iter()
        .map(String::from)
        .collect();
    exts.sort();
    exts.join(",")
}

fn format_option(option: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(ref abbr) = option.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    text.push_str(&format!(
        "--{}{}",
        if option.flag { "(no-)" } else { "" },
        option.full
    ));
    if let Some(ref choices) = option.choices {
        let joined = choices
            .iter()
            .map(|c| match c {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                other => other.to_string(),
            })
            .collect::<Vec<_>>()
            .join("|");
        text.push('=');
        text.push_str(&joined);
    } else if let Some(ref metavar) = option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(ref help) = option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            let def_str = if let Some(ref dh) = option.default_help {
                dh.clone()
            } else if let Some(ref d) = option.default {
                match d {
                    Value::String(s) => s.clone(),
                    Value::Bool(b) => b.to_string(),
                    Value::Number(n) => n.to_string(),
                    other => other.to_string(),
                }
            } else {
                String::new()
            };
            text.push_str(&format!(
                "{}{}",
                " ".repeat(text_length),
                format!("(default: {})", def_str)
            ));
        }
    }
    text
}

fn get_help_text(defs: &[OptionDef]) -> String {
    let mut opts: Vec<&OptionDef> = defs.iter().collect();
    opts.sort_by_key(|o| o.display_index);
    let body = opts
        .iter()
        .map(|o| format_option(o))
        .collect::<Vec<_>>()
        .join("\n");
    // JS uses trimLeft on the template which starts with newline
    format!(
        r#"
Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
"..." behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{body}
"#
    )
    .trim_start()
    .to_string()
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && (value.starts_with("--") || value.starts_with('-'))
}

fn is_option_flag(value: &str) -> bool {
    value.starts_with('-')
}

fn throw_error(exit_code: i32, message: String, help_text: Option<String>) -> ParseError {
    let message = if let Some(ht) = help_text {
        format!("{message}\n\n---\n\n{ht}")
    } else {
        message
    };
    ParseError {
        message,
        exit_code,
    }
}

fn process_value(process: Option<&str>, value: &str) -> Result<Value, ParseError> {
    match process {
        Some("number") => {
            // JS Number(value) — can produce NaN but we try parse
            if let Ok(n) = value.parse::<i64>() {
                Ok(json!(n))
            } else if let Ok(n) = value.parse::<f64>() {
                Ok(json!(n))
            } else {
                Ok(Value::Null) // Number("x") is NaN; serialize as null-ish — actually keep string?
                // Number("abc") is NaN. JSON doesn't have NaN. Use null.
            }
        }
        Some("parser_config") => {
            let content = fs::read_to_string(value).map_err(|e| ParseError {
                message: e.to_string(),
                exit_code: 1,
            })?;
            serde_json::from_str(&content).map_err(|e| ParseError {
                message: e.to_string(),
                exit_code: 1,
            })
        }
        _ => {
            // Try JSON parse like unknown option process
            if let Ok(v) = serde_json::from_str::<Value>(value) {
                Ok(v)
            } else {
                Ok(Value::String(value.to_string()))
            }
        }
    }
}

fn parse_args(
    defs: &[OptionDef],
    by_flag: &HashMap<String, usize>,
    args: Vec<String>,
) -> Result<(CliOptions, Vec<String>), ParseError> {
    let help_text = get_help_text(defs);
    let missing_value = Value::String("__MISSING__".into());

    let mut parsed: Map<String, Value> = Map::new();

    // defaults
    for d in defs {
        if let Some(ref def) = d.default {
            parsed.insert(d.key.clone(), def.clone());
        } else if d.list {
            parsed.insert(d.key.clone(), Value::Array(vec![]));
        }
    }

    let mut positional: Vec<String> = Vec::new();
    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if is_option_flag(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;

            if let Some(idx) = arg.find('=') {
                option_name = arg[..idx].to_string();
                value = Some(arg[idx + 1..].to_string());
            }

            let known = by_flag.get(&option_name).copied();
            let (key, full, flag, list, process, callback) = if let Some(idx) = known {
                let d = &defs[idx];
                (
                    d.key.clone(),
                    d.full.clone(),
                    d.flag,
                    d.list,
                    d.process,
                    d.callback,
                )
            } else {
                // Unknown options are "passed along" (JS behavior)
                let real_option_name = option_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    // handle --no-foo and -x
                    .to_string();
                // JS: optionName.replace(/^--?(no-)?/, '')
                let real_option_name = {
                    let s = option_name.as_str();
                    if let Some(rest) = s.strip_prefix("--no-") {
                        rest.to_string()
                    } else if let Some(rest) = s.strip_prefix("--") {
                        rest.to_string()
                    } else if let Some(rest) = s.strip_prefix('-') {
                        rest.to_string()
                    } else {
                        s.to_string()
                    }
                };

                let is_list = parsed.contains_key(&real_option_name)
                    && parsed.get(&real_option_name) != Some(&Value::Bool(true));
                let flag = !parsed.contains_key(&real_option_name)
                    && value.is_none()
                    && (i + 1 >= args.len() || is_option_flag(&args[i + 1]));

                if is_list {
                    let current = parsed.get(&real_option_name).cloned();
                    if let Some(cv) = current {
                        if !cv.is_array() {
                            if cv == Value::Bool(true) {
                                parsed.insert(real_option_name.clone(), Value::Array(vec![]));
                            } else {
                                parsed.insert(
                                    real_option_name.clone(),
                                    Value::Array(vec![cv]),
                                );
                            }
                        }
                    }
                }

                (
                    real_option_name.clone(),
                    real_option_name,
                    flag,
                    is_list,
                    None,
                    None,
                )
            };

            if let Some(cb) = callback {
                let msg = match cb {
                    "help" => help_text.clone(),
                    "version" => crate::version::version_text(),
                    _ => String::new(),
                };
                return Err(throw_error(0, msg, None));
            } else if flag {
                let v = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if let Some(ref val) = value {
                    Value::Bool(val == "1")
                } else {
                    Value::Bool(true)
                };
                parsed.insert(key, v);
            } else {
                let mut val = value;
                if val.is_none() && i + 1 < args.len() && !is_option_flag(&args[i + 1]) {
                    val = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = val {
                    let processed = if process.is_some() {
                        process_value(process, &v)?
                    } else if known.is_none() {
                        // unknown: try JSON
                        process_value(None, &v)?
                    } else {
                        // known non-process: keep as string (or number process already handled)
                        // JS only runs option.process if defined; otherwise string
                        Value::String(v)
                    };
                    if list {
                        let arr = parsed
                            .entry(key.clone())
                            .or_insert_with(|| Value::Array(vec![]));
                        if let Value::Array(ref mut a) = arr {
                            a.push(processed);
                        }
                    } else {
                        parsed.insert(key, processed);
                    }
                } else {
                    parsed.insert(key, missing_value.clone());
                }
            }
            let _ = full; // silence
        } else {
            // positional: number if all digits
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                // JS pushes Number(arg) but paths are later strings; keep string for paths
                // Actually positional numbers become numbers in JS — but used as paths
                // Coerce via toString when used. Keep as string representation.
                positional.push(arg.clone());
            } else {
                positional.push(arg.clone());
            }
        }
        i += 1;
    }

    // missing values
    for d in defs {
        if parsed.get(&d.key) == Some(&missing_value) {
            return Err(throw_error(
                1,
                format!("Missing value: --{} requires a value", d.full),
                Some(help_text.clone()),
            ));
        }
    }

    // validate choices
    let mut errors = Vec::new();
    for d in defs {
        if let Some(ref choices) = d.choices {
            if let Some(val) = parsed.get(&d.key) {
                let ok = choices.iter().any(|c| {
                    // verbose choices are numbers; parser are strings
                    c == val
                        || (c.as_i64().is_some()
                            && val.as_i64() == c.as_i64())
                        || (c.as_str().is_some() && val.as_str() == c.as_str())
                        // Number from process might be number while choice is number
                        || match (c, val) {
                            (Value::Number(a), Value::String(s)) => {
                                s.parse::<i64>().ok() == a.as_i64()
                            }
                            (Value::String(a), Value::Number(b)) => {
                                a.parse::<i64>().ok() == b.as_i64()
                            }
                            _ => false,
                        }
                });
                if !ok {
                    let choice_str = choices
                        .iter()
                        .map(|c| match c {
                            Value::String(s) => s.clone(),
                            Value::Number(n) => n.to_string(),
                            o => o.to_string(),
                        })
                        .collect::<Vec<_>>()
                        .join(",");
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        d.full, choice_str
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(throw_error(1, errors.join("\n"), Some(help_text)));
    }

    let get_bool = |k: &str, default: bool| {
        parsed
            .get(k)
            .and_then(|v| v.as_bool())
            .unwrap_or(default)
    };
    let get_string = |k: &str, default: &str| {
        parsed
            .get(k)
            .and_then(|v| match v {
                Value::String(s) => Some(s.clone()),
                Value::Number(n) => Some(n.to_string()),
                _ => None,
            })
            .unwrap_or_else(|| default.to_string())
    };
    let get_i32 = |k: &str, default: i32| {
        parsed
            .get(k)
            .and_then(|v| {
                v.as_i64()
                    .map(|n| n as i32)
                    .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
            })
            .unwrap_or(default)
    };
    let get_list = |k: &str| {
        parsed
            .get(k)
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .map(|v| match v {
                        Value::String(s) => s.clone(),
                        other => other.to_string(),
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default()
    };

    let cpus = parsed.get("cpus").and_then(|v| {
        v.as_u64()
            .map(|n| n as usize)
            .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
    });

    let parser_config = parsed.get("parserConfig").cloned().and_then(|v| {
        if v.is_null() {
            None
        } else {
            Some(v)
        }
    });

    let opts = CliOptions {
        transform: get_string("transform", "./transform.js"),
        cpus,
        verbose: get_i32("verbose", 0),
        dry: get_bool("dry", false),
        print: get_bool("print", false),
        babel: get_bool("babel", true),
        extensions: get_string("extensions", &default_extensions_string()),
        ignore_pattern: get_list("ignorePattern"),
        ignore_config: get_list("ignoreConfig"),
        gitignore: get_bool("gitignore", false),
        run_in_band: get_bool("runInBand", false),
        silent: get_bool("silent", false),
        parser: get_string("parser", "babel"),
        parser_config,
        fail_on_error: get_bool("failOnError", false),
        stdin: get_bool("stdin", false),
        extra: parsed,
    };

    let _ = Path::new("."); // silence unused import if any
    Ok((opts, positional))
}

