{"path":"/workspace/codebase/rust/src/ignore.rs","command":"create","file_text":"//! Ignore-pattern handling mirroring `src/ignoreFiles.js`.

use globset::{Glob, GlobSet, GlobSetBuilder};
use once_cell::sync::Lazy;
use std::fs;
use std::path::Path;
use std::sync::Mutex;

static MATCHERS: Lazy<Mutex<Vec<String>>> = Lazy::new(|| Mutex::new(Vec::new()));

/// Add glob patterns to ignore matched files and folders.
/// Creates glob patterns to approximate gitignore patterns.
pub fn add_ignore_pattern(val: &str) {
    if val.is_empty() || val.starts_with('#') {
        return;
    }
    let pattern = val.to_string();
    let mut matchers = MATCHERS.lock().unwrap();
    if !pattern.contains('/') {
        matchers.push(format!("**/{}", pattern));
    } else if pattern.ends_with('/') {
        matchers.push(format!("**/{}**", pattern));
        matchers.push(format!("{}**", pattern));
    }
    matchers.push(pattern);
}

pub fn add(input: &[String]) {
    for p in input {
        add_ignore_pattern(p);
    }
}

pub fn add_from_file(input: &[String]) {
    for config in input {
        let path = Path::new(config);
        if let Ok(meta) = fs::metadata(path) {
            if meta.is_file() {
                if let Ok(content) = fs::read_to_string(path) {
                    for line in content.split('\n') {
                        // also handle \r\n
                        let line = line.trim_end_matches('\r');
                        add_ignore_pattern(line);
                    }
                }
            }
        }
    }
}

pub fn add_from_file_path(path: &Path) {
    add_from_file(&[path.to_string_lossy().to_string()]);
}

pub fn should_ignore(path: &str) -> bool {
    let matchers = MATCHERS.lock().unwrap();
    if matchers.is_empty() {
        return false;
    }

    // Strip leading ../ or ./ traversal prefixes (issue #556)
    let normalized = strip_traversal_prefix(path);

    match_any(path, &matchers) || (normalized != path && match_any(&normalized, &matchers))
}

fn strip_traversal_prefix(path: &str) -> String {
    // path.replace(/^(?:\.\.?[/\\])+/, '')
    let mut s = path;
    loop {
        if s.starts_with("../") || s.starts_with("..\\") {
            s = &s[3..];
        } else if s.starts_with("./") || s.starts_with(".\\") {
            s = &s[2..];
        } else {
            break;
        }
    }
    s.to_string()
}

fn match_any(path: &str, patterns: &[String]) -> bool {
    let mut builder = GlobSetBuilder::new();
    let mut any = false;
    for p in patterns {
        // picomatch with { dot: true }
        // Convert picomatch-ish patterns; globset is close enough for ** and *
        if let Ok(g) = Glob::new(p) {
            builder.add(g);
            any = true;
        } else {
            // try escaping nothing — skip invalid
        }
    }
    if !any {
        return false;
    }
    let set: GlobSet = match builder.build() {
        Ok(s) => s,
        Err(_) => return false,
    };
    // Also try matching with literal options. globset doesn't have dot:true equivalent
    // but ** matches hidden segments by default in globset.
    set.is_match(path)
}

/// Reset matchers (for tests / fresh runs in-process).
#[allow(dead_code)]
pub fn reset() {
    MATCHERS.lock().unwrap().clear();
}","security_risk":"LOW","summary":"Create ignore module"}

{"path":"/workspace/codebase/rust/src/color.rs","command":"create","file_text":"//! Terminal colors mirroring picocolors usage in Runner.js.

use std::io::IsTerminal;
use std::sync::atomic::{AtomicBool, Ordering};

static COLOR: AtomicBool = AtomicBool::new(true);

pub fn init() {
    let no_color = std::env::var_os("NO_COLOR").is_some()
        || std::env::args().any(|a| a == "--no-color");
    let force = std::env::var_os("FORCE_COLOR").is_some()
        || std::env::args().any(|a| a == "--color")
        || std::env::var_os("CI").is_some();
    let tty = std::io::stdout().is_terminal();
    COLOR.store((!no_color) && (force || tty), Ordering::Relaxed);
}

fn enabled() -> bool {
    COLOR.load(Ordering::Relaxed)
}

fn wrap(open: &str, close: &str, s: &str) -> String {
    if enabled() {
        format!("{open}{s}{close}")
    } else {
        s.to_string()
    }
}

pub fn white(s: &str) -> String {
    wrap("\x1b[37m", "\x1b[39m", s)
}
pub fn red(s: &str) -> String {
