{"path":"/workspace/codebase/rust/src/version.rs","command":"create","file_text":"//! Version string matching the JS CLI --version callback.

use std::path::{Path, PathBuf};
use std::process::Command;

fn package_root() -> PathBuf {
    // binary is typically at <root>/bin/jscodeshift-rs or target/…; find package via env or cwd
    if let Ok(p) = std::env::var("JSCODESHIFT_ROOT") {
        return PathBuf::from(p);
    }
    // Try relative to executable
    if let Ok(exe) = std::env::current_exe() {
        // bin/jscodeshift wrapper or rust target
        if let Some(parent) = exe.parent() {
            // if exe is root/bin/jscodeshift-native
            let candidate = parent.parent().unwrap_or(parent);
            if candidate.join("package.json").exists() {
                return candidate.to_path_buf();
            }
            // if in target/release
            if let Some(r) = find_up(parent, "package.json") {
                return r;
            }
        }
    }
    std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn find_up(start: &Path, file: &str) -> Option<PathBuf> {
    let mut dir = start.to_path_buf();
    loop {
        if dir.join(file).exists() {
            return Some(dir);
        }
        if !dir.pop() {
            return None;
        }
    }
}

fn read_pkg_version(name: &str, root: &Path) -> String {
    // Try node -e require
    let script = format!(
        "try{{const p=require('{}');const path=require('path');const fs=require('fs');let entry;try{{entry=require.resolve('{}')}}catch(e){{console.log('');process.exit(0)}};let dir=path.dirname(entry);while(dir!=='/'){{try{{const pkg=require(path.join(dir,'package.json'));if(pkg.name==='{}'){{console.log(pkg.version||'');process.exit(0)}}}}catch(e){{}}dir=path.dirname(dir)}};console.log('')}}catch(e){{console.log('')}}",
        name.replace('\'', "\\'"),
        name.replace('\'', "\\'"),
        name.replace('\'', "\\'")
    );
    // Simpler approach
    let _ = root;
    let out = Command::new("node")
        .arg("-e")
        .arg(format!(
            r#"
const path = require('path');
function requirePackage(name) {{
  try {{
    const entry = require.resolve(name);
    let dir = path.dirname(entry);
    while (dir !== path.parse(dir).root && dir !== '/') {{
      try {{
        const pkg = require(path.join(dir, 'package.json'));
        if (pkg.name === name) return pkg;
      }} catch (e) {{}}
      dir = path.dirname(dir);
    }}
  }} catch (e) {{}}
  return {{}};
}}
const name = process.argv[1];
const pkg = name === '@babel/core' ? require('@babel/core') : requirePackage(name);
if (name === '@babel/core') console.log(pkg.version || '');
else console.log(pkg.version || '');
"#,
        ))
        .arg(name)
        .current_dir(root)
        .output();
    match out {
        Ok(o) => String::from_utf8_lossy(&o.stdout).trim().to_string(),
        Err(_) => String::new(),
    }
}

fn jscodeshift_version(root: &Path) -> String {
    let pkg_path = root.join("package.json");
    if let Ok(content) = std::fs::read_to_string(&pkg_path) {
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(&content) {
            if let Some(ver) = v.get("version").and_then(|x| x.as_str()) {
                return ver.to_string();
            }
        }
    }
    env!("CARGO_PKG_VERSION").to_string()
}

pub fn version_text() -> String {
    let root = package_root();
    let jsc = jscodeshift_version(&root);
    let babel = read_pkg_version("@babel/core", &root);
    let babylon = read_pkg_version("@babel/parser", &root);
    let flow = read_pkg_version("flow-parser", &root);
    let recast = read_pkg_version("recast", &root);
    format!(
        "jscodeshift: {jsc}\n - babel: {babel}\n - babylon: {babylon}\n - flow: {flow}\n - recast: {recast}\n"
    )
}","security_risk":"LOW","summary":"Create version module"}

{"path":"/workspace/codebase/rust/src/runner.rs","command":"create","file_text":"//! Runner: file discovery, worker orchestration, stats — mirrors `src/Runner.js`.

use crate::color;
use crate::ignore;
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::collections::BTreeMap;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

#[derive(Debug, Clone)]
pub struct RunOptions {
    pub transform_file: String,
    pub paths: Vec<String>,
    pub cpus: Option<usize>,
    pub verbose: i32,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: String,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<Value>,
    pub fail_on_error: bool,
    pub extra: Map<String, Value>,
}

#[derive(Debug, Default, Clone)]
pub struct FileStats {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
    pub stats: BTreeMap<String, i64>,
    pub time_elapsed: String,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "action")]
enum WorkerMessage {
    #[serde(rename = "status")]
    Status { status: String, msg: String },
    #[serde(rename = "update")]
    Update { name: String, quantity: i64 },
    #[serde(rename = "free")]
    Free,
    #[serde(rename = "report")]
    Report { file: String, msg: String },
    #[serde(rename = "done")]
    Done,
    #[serde(rename = "error")]
    Error { message: String },
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{s}\n")
    }
}

fn available_cpus() -> usize {
    num_cpus::get().saturating_sub(1).max(1)
}

fn package_root() -> PathBuf {
    if let Ok(p) = std::env::var("JSCODESHIFT_ROOT") {
        return PathBuf::from(p);
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(parent) = exe.parent() {
            if let Some(r) = find_up(parent, "package.json") {
                return r;
            }
            if let Some(gp) = parent.parent() {
                if gp.join("package.json").exists() {
                    return gp.to_path_buf();
                }
            }
        }
    }
    std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn find_up(start: &Path, file: &str) -> Option<PathBuf> {
    let mut dir = start.to_path_buf();
    loop {
        if dir.join(file).exists() {
            return Some(dir);
        }
        if !dir.pop() {
            return None;
        }
    }
}

fn bridge_script_path() -> PathBuf {
    package_root().join("bridge").join("transform-host.js")
}

fn resolve_path_like_js(p: &str) -> PathBuf {
    let path = PathBuf::from(p);
    if path.is_absolute() {
        path
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(path)
    }
}

/// Recursively list files under dir (with trailing semantics like JS).
fn dir_files(dir: &Path, out: &mut Vec<String>) -> Result<(), String> {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(e) => return Err(e.to_string()),
    };
    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let name = entry.path();
        let name_str = name.to_string_lossy().to_string();
        // On Windows we'd care about separators; normalize to keep as produced
        match fs::symlink_metadata(&name).and_then(|m| {
            if m.file_type().is_symlink() {
                // JS uses fs.stat which follows; if broken, skip
                fs::metadata(&name).map(|mm| (mm, name_str.clone()))
            } else {
                Ok((m, name_str.clone()))
            }
        }) {
            Err(_) => {
                print!("Skipping path \"{}\" which does not exist.\n", name_str);
                continue;
            }
            Ok((stats, _)) => {
                if ignore::should_ignore(&name_str) {
                    continue;
                } else if stats.is_dir() {
                    // JS joins with name + '/'
                    dir_files(&name, out)?;
                } else {
                    out.push(name_str);
                }
            }
        }
    }
    Ok(())
}

fn get_all_files(paths: &[String], extensions: &Option<Vec<String>>) -> Vec<String> {
    let mut result = Vec::new();
    for file in paths {
        if file.is_empty() {
            // still try — will not exist
        }
        let path = PathBuf::from(file);
        match fs::symlink_metadata(&path) {
            Err(_) => {
                eprint!("Skipping path {} which does not exist. \n", file);
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut list = Vec::new();
                    if let Err(e) = dir_files(&path, &mut list) {
                        // JS throws on readdir error
                        panic!("{}", e);
                    }
                    for name in list {
                        if extension_ok(&name, extensions) {
                            result.push(name);
                        }
                    }
                } else if !extension_ok(file, extensions) || ignore::should_ignore(file) {
                    // ignore
                } else {
                    result.push(file.to_string());
                }
            }
        }
    }
    result
}

fn extension_ok(name: &str, extensions: &Option<Vec<String>>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name)
                .extension()
                .map(|e| format!(".{}", e.to_string_lossy()))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

fn show_file_stats(file_stats: &FileStats) {
    print!(
        "Results: \n{}{}{}{}",
        crate::color::red(&format!("{} errors\n", file_stats.error)),
        crate::color::yellow(&format!("{} unmodified\n", file_stats.nochange)),
        crate::color::yellow(&format!("{} skipped\n", file_stats.skip)),
        crate::color::green(&format!("{} ok\n", file_stats.ok)),
    );
}

fn show_stats(stats: &BTreeMap<String, i64>) {
    if !stats.is_empty() {
        print!("{}", crate::color::blue("Stats: \n"));
    }
    for (name, val) in stats {
        print!("{}: {}\n", name, val);
    }
}

fn log_status(status: &str, msg: &str, verbose: i32) {
    let msg = line_break(msg);
    match status {
        "ok" if verbose >= 2 => {
            print!("{}{}", color::ok_tag(), msg);
        }
        "nochange" if verbose >= 1 => {
            print!("{}{}", color::noc_tag(), msg);
        }
        "skip" if verbose >= 1 => {
            print!("{}{}", color::skip_tag(), msg);
        }
        "error" if verbose >= 0 => {
            print!("{}{}", color::err_tag(), msg);
        }
        _ => {}
    }
}

fn report(file: &str, msg: &str) {
    print!("{}", line_break(&format!("{}{} {}", color::rep_tag(), file, msg)));
}

fn options_to_json(opts: &RunOptions) -> Value {
    // Build the options object as the JS worker expects (camelCase keys from args parser)
    let mut m = opts.extra.clone();
    // Ensure known fields are present with correct types
    m.insert("dry".into(), json!(opts.dry));
    m.insert("print".into(), json!(opts.print));
    m.insert("babel".into(), json!(opts.babel));
    m.insert("verbose".into(), json!(opts.verbose));
    m.insert("silent".into(), json!(opts.silent));
    m.insert("runInBand".into(), json!(opts.run_in_band));
    m.insert("failOnError".into(), json!(opts.fail_on_error));
    m.insert("parser".into(), json!(opts.parser));
    m.insert("extensions".into(), json!(opts.extensions));
    m.insert("gitignore".into(), json!(opts.gitignore));
    m.insert("transform".into(), json!(opts.transform_file));
    if let Some(ref pc) = opts.parser_config {
        m.insert("parserConfig".into(), pc.clone());
    }
    if let Some(c) = opts.cpus {
        m.insert("cpus".into(), json!(c));
    }
    m.insert("ignorePattern".into(), json!(opts.ignore_pattern));
    m.insert("ignoreConfig".into(), json!(opts.ignore_config));
    Value::Object(m)
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let client = reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(120))
        .build()
        .map_err(|e| e.to_string())?;
    let resp = client.get(url).send().map_err(|e| e.to_string())?;
    if !resp.status().is_success() {
        return Err(format!("HTTP {} fetching transform", resp.status()));
    }
    let contents = resp.bytes().map_err(|e| e.to_string())?;
    let ext = Path::new(url)
        .extension()
        .map(|e| format!(".{}", e.to_string_lossy()))
        .unwrap_or_default();
    let tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()
        .map_err(|e| e.to_string())?;
    let (mut f, path) = tmp.keep().map_err(|e| e.to_string())?;
    f.write_all(&contents).map_err(|e| e.to_string())?;
    Ok(path)
}

pub fn run(options: RunOptions) -> Result<FileStats, String> {
    color::init();
    ignore::reset();

    let cpus = options
        .cpus
        .map(|c| c.min(available_cpus()))
        .unwrap_or_else(available_cpus);

    let extensions: Option<Vec<String>> = if options.extensions.is_empty() {
        None
    } else {
        Some(
            options
                .extensions
                .split(',')
                .map(|ext| format!(".{}", ext))
                .collect(),
        )
    };

    ignore::add(&options.ignore_pattern);
    // ignoreSet is referenced in JS but never set by CLI — skip
    ignore::add_from_file(&options.ignore_config);

    if options.gitignore {
        let git_ignore = std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(".gitignore");
        ignore::add_from_file_path(&git_ignore);
    }

    let transform_file = if options.transform_file.starts_with("http://")
        || options.transform_file.starts_with("https://")
    {
        download_transform(&options.transform_file)?
            .to_string_lossy()
            .to_string()
    } else {
        let p = resolve_path_like_js(&options.transform_file);
        // JS checks existsSync on the path as given after resolve
        if !Path::new(&options.transform_file).exists() && !p.exists() {
            eprint!(
                "{} Transform file {} does not exist \n",
                color::error_banner(),
                options.transform_file
            );
            return Ok(FileStats::default());
        }
        // Prefer the path that exists
        if p.exists() {
            p.to_string_lossy().to_string()
        } else {
            options.transform_file.clone()
        }
    };

    transform_files(&transform_file, &options, extensions.as_ref(), cpus)
}

fn transform_files(
    transform_file: &str,
    options: &RunOptions,
    extensions: Option<&Vec<String>>,
    cpus: usize,
) -> Result<FileStats, String> {
    let start = Instant::now();
    let files = get_all_files(&options.paths, &extensions.cloned());
    let num_files = files.len();

    if num_files == 0 {
        print!("No files selected, nothing to do. \n");
        return Ok(FileStats::default());
    }

    let processes = if options.run_in_band {
        1
    } else {
        num_files.min(cpus)
    };
    let chunk_size = if processes > 1 {
        ((num_files + processes - 1) / processes).min(CHUNK_SIZE)
    } else {
        num_files
    };

    if !options.silent {
        print!("Processing {} files... \n", files.len());
        if !options.run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if options.dry {
            print!(
                "{}",
                color::green("Running in dry mode, no files will be written! \n")
            );
        }
    }

    let file_counters = Arc::new(Mutex::new(FileStats::default()));
    let stats_counter: Arc<Mutex<BTreeMap<String, i64>>> = Arc::new(Mutex::new(BTreeMap::new()));
    let next_index = Arc::new(AtomicUsize::new(0));
    let files = Arc::new(files);
    let opts_json = options_to_json(options);
    let babel_arg = if options.babel { "babel" } else { "no-babel" };
    let bridge = bridge_script_path();
    if !bridge.exists() {
        return Err(format!(
            "Transform bridge not found at {}. Run app-setup/build.sh first.",
            bridge.display()
        ));
    }
    let root = package_root();
    let verbose = options.verbose;
    let silent = options.silent;
    let run_in_band = options.run_in_band;

    let mut handles = Vec::new();

    for _worker_id in 0..processes {
        let files = Arc::clone(&files);
        let next_index = Arc::clone(&next_index);
        let file_counters = Arc::clone(&file_counters);
        let stats_counter = Arc::clone(&stats_counter);
        let opts_json = opts_json.clone();
        let transform_file = transform_file.to_string();
        let babel_arg = babel_arg.to_string();
        let bridge = bridge.clone();
        let root = root.clone();
        let chunk_size = chunk_size;
        let num_files = num_files;

        let handle = thread::spawn(move || {
            // Spawn node bridge worker
            let mut child = match spawn_worker(&bridge, &transform_file, &babel_arg, &root) {
                Ok(c) => c,
                Err(e) => {
                    let mut fc = file_counters.lock().unwrap();
                    fc.error += 1;
                    log_status("error", &format!("worker spawn: {e}"), verbose);
                    return;
                }
            };

            let mut stdin = child.stdin.take().expect("stdin");
            let stdout = child.stdout.take().expect("stdout");
            let mut reader = BufReader::new(stdout);

            loop {
                let idx = next_index.fetch_add(chunk_size, Ordering::SeqCst);
                if idx >= num_files {
                    // signal end
                    let _ = writeln!(stdin, "{}", json!({"action":"end"}));
                    let _ = stdin.flush();
                    break;
                }
                let end = (idx + chunk_size).min(num_files);
                let chunk: Vec<String> = files[idx..end].to_vec();

                if !silent && !run_in_band && idx < num_files {
                    print!(
                        "Sending {} files to free worker...\n",
                        end - idx
                    );
                    let _ = std::io::stdout().flush();
                }

                let msg = json!({
                    "action": "run",
                    "files": chunk,
                    "options": opts_json,
                });
                if writeln!(stdin, "{}", msg).is_err() {
                    break;
                }
                if stdin.flush().is_err() {
                    break;
                }

                // Read messages until free or done
                let mut line = String::new();
                loop {
                    line.clear();
                    match reader.read_line(&mut line) {
                        Ok(0) => break, // EOF
                        Ok(_) => {
                            let line = line.trim();
                            if line.is_empty() {
                                continue;
                            }
                            match serde_json::from_str::<WorkerMessage>(line) {
                                Ok(WorkerMessage::Status { status, msg }) => {
                                    let mut fc = file_counters.lock().unwrap();
                                    match status.as_str() {
                                        "error" => fc.error += 1,
                                        "ok" => fc.ok += 1,
                                        "nochange" => fc.nochange += 1,
                                        "skip" => fc.skip += 1,
                                        _ => {}
                                    }
                                    drop(fc);
                                    log_status(&status, &msg, verbose);
                                }
                                Ok(WorkerMessage::Update { name, quantity }) => {
                                    let mut sc = stats_counter.lock().unwrap();
                                    *sc.entry(name).or_insert(0) += quantity;
                                }
                                Ok(WorkerMessage::Report { file, msg }) => {
                                    report(&file, &msg);
                                }
                                Ok(WorkerMessage::Free) => {
                                    break; // get next chunk
                                }
                                Ok(WorkerMessage::Done) => {
                                    return;
                                }
                                Ok(WorkerMessage::Error { message }) => {
                                    let mut fc = file_counters.lock().unwrap();
                                    fc.error += 1;
                                    log_status("error", &message, verbose);
                                }
                                Err(e) => {
                                    // Might be non-JSON log lines from transform console
                                    // Ignore or print
                                    if !line.is_empty() {
                                        eprintln!("[worker] {} ({})", line, e);
                                    }
                                }
                            }
                        }
                        Err(_) => break,
                    }
                }
            }

            // Drain remaining
            let mut line = String::new();
            while let Ok(n) = reader.read_line(&mut line) {
                if n == 0 {
                    break;
                }
                let trimmed = line.trim();
                if let Ok(msg) = serde_json::from_str::<WorkerMessage>(trimmed) {
                    match msg {
                        WorkerMessage::Status { status, msg } => {
                            let mut fc = file_counters.lock().unwrap();
                            match status.as_str() {
                                "error" => fc.error += 1,
                                "ok" => fc.ok += 1,
                                "nochange" => fc.nochange += 1,
                                "skip" => fc.skip += 1,
                                _ => {}
                            }
                            drop(fc);
                            log_status(&status, &msg, verbose);
                        }
                        WorkerMessage::Update { name, quantity } => {
                            let mut sc = stats_counter.lock().unwrap();
                            *sc.entry(name).or_insert(0) += quantity;
                        }
                        WorkerMessage::Report { file, msg } => report(&file, &msg),
                        _ => {}
                    }
                }
                line.clear();
            }
            let _ = child.wait();
        });
        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    let elapsed = start.elapsed().as_secs_f64();
    let time_elapsed = format!("{:.3}", elapsed);

    let mut result = file_counters.lock().unwrap().clone();
    result.stats = stats_counter.lock().unwrap().clone();
    result.time_elapsed = time_elapsed.clone();

    if !options.silent {
        print!("All done. \n");
        show_file_stats(&result);
        show_stats(&result.stats);
        print!("Time elapsed: {}seconds \n", time_elapsed);
    }

    Ok(result)
}

fn spawn_worker(
    bridge: &Path,
    transform_file: &str,
    babel_arg: &str,
    root: &Path,
) -> Result<Child, String> {
    Command::new("node")
        .arg(bridge)
        .arg(transform_file)
        .arg(babel_arg)
        .current_dir(root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .env("JSCODESHIFT_ROOT", root)
        .spawn()
        .map_err(|e| e.to_string())
}","security_risk":"LOW","summary":"Create runner module"}

{"path":"/workspace/codebase/bridge/transform-host.js","command":"create","file_text":"#!/usr/bin/env node
/**
 * Minimal Node.js compatibility bridge for executing user transforms.
 * Protocol (newline-delimited JSON on stdin/stdout):
 *   → { "action": "run", "files": [...], "options": {...} }
 *   → { "action": "end" }
 *   ← { "action": "status", "status": "ok|error|nochange|skip", "msg": "..." }
 *   ← { "action": "update", "name": "...", "quantity": N }
 *   ← { "action": "report", "file": "...", "msg": "..." }
 *   ← { "action": "free" }
 *   ← { "action": "done" }
 *
 * Copyright (c) Facebook, Inc. and its affiliates. MIT license.
 */
'use strict';

const fs = require('graceful-fs');
const path = require('path');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const readline = require('readline');

const root = process.env.JSCODESHIFT_ROOT || path.resolve(__dirname, '..');
const getParser = require(path.join(root, 'src', 'getParser'));
const jscodeshift = require(path.join(root, 'src', 'core'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

const transformFile = process.argv[2];
const babel = process.argv[3];

let transform;
let parserFromTransform;

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babelFlag) {
  if (babelFlag === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        {targets: {node: true}},
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr) ?
        require('@babel/preset-typescript').default :
        require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const mod = require(tr);
  transform = typeof mod.default === 'function' ? mod.default : mod;
  if (mod.parser) {
    parserFromTransform = typeof mod.parser === 'string' ?
      getParser(mod.parser) :
      mod.parser;
  }
}

function send(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  send({action: 'status', status: status, msg: msg});
}

function report(file, msg) {
  send({action: 'report', file, msg});
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  send({action: 'update', name: name, quantity: quantity});
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  const self = __filename;
  lines.every(function(line) {
    if (line.indexOf(self) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function processFile(file, options) {
  return new Promise((resolve) => {
    fs.readFile(file, async function(err, source) {
      if (err) {
        updateStatus('error', file, 'File error: ' + err);
        resolve();
        return;
      }
      source = source.toString();
      try {
        const j = prepareJscodeshift(options);
        const out = await transform(
          {
            path: file,
            source: source,
          },
          {
            j: j,
            jscodeshift: j,
            stats: options.dry ? stats : empty,
            report: msg => report(file, msg),
          },
          options
        );
        if (!out || out === source) {
          updateStatus(out ? 'nochange' : 'skip', file);
          resolve();
          return;
        }
        if (options.print) {
          console.log(out); // eslint-disable-line no-console
        }
        if (!options.dry) {
          writeFileAtomic(file, out, function(err) {
            if (err) {
              updateStatus('error', file, 'File writer error: ' + err);
            } else {
              updateStatus('ok', file);
            }
            resolve();
          });
        } else {
          updateStatus('ok', file);
          resolve();
        }
      } catch (err) {
        updateStatus(
          'error',
          file,
          'Transformation error ('+ (err.message || '').replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack)
        );
        resolve();
      }
    });
  });
}

async function runFiles(files, options) {
  for (const file of files) {
    await processFile(file, options || {});
  }
  send({action: 'free'});
}

try {
  setup(transformFile, babel);
} catch (err) {
  send({action: 'error', message: 'Setup error: ' + (err && err.stack ? err.stack : err)});
  process.exit(1);
}

const rl = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });

rl.on('line', async (line) => {
  line = line.trim();
  if (!line) return;
  let msg;
  try {
    msg = JSON.parse(line);
  } catch (e) {
    return;
  }
  if (msg.action === 'end') {
    send({action: 'done'});
    rl.close();
    process.exit(0);
    return;
  }
  if (msg.action === 'run') {
    try {
      await runFiles(msg.files || [], msg.options || {});
    } catch (err) {
      send({action: 'error', message: String(err)});
      send({action: 'free'});
    }
  }
});

rl.on('close', () => {
  send({action: 'done'});
});
