/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 *
 * Launcher for the Rust jscodeshift CLI. Falls back to locating the
 * native binary built by app-setup/build.sh.
 */
'use strict';

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
process.env.JSCODESHIFT_ROOT = root;

function candidateBinaries() {
  const names = [
    process.env.JSCODESHIFT_NATIVE,
    path.join(root, 'bin', 'jscodeshift-native'),
    path.join(root, 'bin', 'jscodeshift-rs'),
    path.join(root, 'target', 'release', 'jscodeshift'),
    path.join(root, 'rust', 'target', 'release', 'jscodeshift'),
    path.join(root, '..', '.cargo-target', 'release', 'jscodeshift'),
  ].filter(Boolean);

  // Also check CARGO_TARGET_DIR
  if (process.env.CARGO_TARGET_DIR) {
    names.push(path.join(process.env.CARGO_TARGET_DIR, 'release', 'jscodeshift'));
  }
  return names;
}

function findBinary() {
  for (const p of candidateBinaries()) {
    try {
      if (p && fs.existsSync(p) && fs.statSync(p).isFile()) {
        return p;
      }
    } catch (_) {}
  }
  return null;
}

const bin = findBinary();
if (!bin) {
  process.stderr.write(
    'jscodeshift: native binary not found. Run app-setup/build.sh first.\n'
  );
  process.exit(1);
}

const result = spawnSync(bin, process.argv.slice(2), {
  stdio: 'inherit',
  env: Object.assign({}, process.env, { JSCODESHIFT_ROOT: root }),
});

if (result.error) {
  process.stderr.write(String(result.error) + '\n');
  process.exit(1);
}
process.exit(result.status == null ? 1 : result.status);
