{"path":"/workspace/codebase/src/Runner.js","command":"create","file_text":"/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 *
 * Programmatic runner API. Delegates to the Rust jscodeshift binary while
 * preserving the historical `require('jscodeshift/src/Runner').run` shape.
 */
'use strict';

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');

const root = path.resolve(__dirname, '..');

function findBinary() {
  const names = [
    process.env.JSCODESHIFT_NATIVE,
    path.join(root, 'bin', 'jscodeshift-native'),
    path.join(root, 'bin', 'jscodeshift-rs'),
    path.join(root, 'target', 'release', 'jscodeshift'),
    path.join(root, 'rust', 'target', 'release', 'jscodeshift'),
    path.join(root, '..', '.cargo-target', 'release', 'jscodeshift'),
  ];
  if (process.env.CARGO_TARGET_DIR) {
    names.push(path.join(process.env.CARGO_TARGET_DIR, 'release', 'jscodeshift'));
  }
  for (const p of names) {
    if (p && fs.existsSync(p)) return p;
  }
  return null;
}

/**
 * Convert options object to CLI argv flags (best-effort for known keys).
 */
function optionsToArgs(options) {
  const args = [];
  if (!options) return args;

  const flagMap = {
    dry: { flag: true, name: '--dry' },
    print: { flag: true, name: '--print' },
    babel: { flag: true, name: '--babel', neg: '--no-babel' },
    silent: { flag: true, name: '--silent' },
    runInBand: { flag: true, name: '--run-in-band' },
    failOnError: { flag: true, name: '--fail-on-error' },
    gitignore: { flag: true, name: '--gitignore' },
    stdin: { flag: true, name: '--stdin' },
    verbose: { name: '--verbose' },
    cpus: { name: '--cpus' },
    extensions: { name: '--extensions' },
    parser: { name: '--parser' },
    parserConfig: { name: '--parser-config', file: true },
  };

  for (const [key, val] of Object.entries(options)) {
    if (key === 'transform' || key === 'paths') continue;
    const meta = flagMap[key];
    if (!meta) {
      // custom option — pass as --key=json
      if (typeof val === 'boolean') {
        args.push(val ? `--${key}` : `--no-${key}`);
      } else if (Array.isArray(val)) {
        for (const v of val) args.push(`--${key}`, String(v));
      } else if (val != null) {
        args.push(`--${key}`, typeof val === 'object' ? JSON.stringify(val) : String(val));
      }
      continue;
    }
    if (meta.flag) {
      if (key === 'babel') {
        args.push(val ? '--babel' : '--no-babel');
      } else if (val) {
        args.push(meta.name);
      }
    } else if (val != null) {
      if (meta.file && typeof val === 'object') {
        const tmp = path.join(os.tmpdir(), `jscodeshift-parser-config-${process.pid}.json`);
        fs.writeFileSync(tmp, JSON.stringify(val));
        args.push(meta.name, tmp);
      } else {
        args.push(meta.name, String(val));
      }
    }
  }

  if (options.ignorePattern) {
    const pats = [].concat(options.ignorePattern);
    for (const p of pats) {
      args.push('--ignore-pattern', p);
    }
  }
  if (options.ignoreConfig) {
    const confs = [].concat(options.ignoreConfig);
    for (const c of confs) {
      args.push('--ignore-config', c);
    }
  }

  return args;
}

/**
 * @param {string} transformFile
 * @param {string[]} paths
 * @param {object} options
 * @returns {Promise<object>}
 */
function run(transformFile, paths, options) {
  options = options || {};
  const bin = findBinary();
  if (!bin) {
    return Promise.reject(
      new Error('jscodeshift native binary not found. Run app-setup/build.sh first.')
    );
  }

  const args = ['-t', transformFile, '--run-in-band'];
  // run-in-band by default for programmatic? No — honor options
  // Remove the forced run-in-band; rebuild args properly
  const args2 = ['-t', transformFile];
  args2.push(...optionsToArgs(options));
  for (const p of paths || []) {
    args2.push(p);
  }

  return new Promise((resolve, reject) => {
    const child = spawn(bin, args2, {
      env: Object.assign({}, process.env, { JSCODESHIFT_ROOT: root }),
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => {
      stdout += d.toString();
      if (!options.silent) process.stdout.write(d);
    });
    child.stderr.on('data', (d) => {
      stderr += d.toString();
      if (!options.silent) process.stderr.write(d);
    });
    child.on('error', reject);
    child.on('close', (code) => {
      // Parse summary from stdout if possible
      const stats = { error: 0, ok: 0, nochange: 0, skip: 0, stats: {}, timeElapsed: '0' };
      const errMatch = stdout.match(/(\d+) errors/);
      const nocMatch = stdout.match(/(\d+) unmodified/);
      const skipMatch = stdout.match(/(\d+) skipped/);
      const okMatch = stdout.match(/(\d+) ok/);
      const timeMatch = stdout.match(/Time elapsed: ([0-9.]+)seconds/);
      if (errMatch) stats.error = Number(errMatch[1]);
      if (nocMatch) stats.nochange = Number(nocMatch[1]);
      if (skipMatch) stats.skip = Number(skipMatch[1]);
      if (okMatch) stats.ok = Number(okMatch[1]);
      if (timeMatch) stats.timeElapsed = timeMatch[1];
      if (options.failOnError && stats.error > 0) {
        const e = new Error('jscodeshift failed with errors');
        e.stats = stats;
        e.code = 1;
        reject(e);
        return;
      }
      resolve(stats);
    });
  });
}

exports.run = run;
