  pushFlag(options.dry, '--dry');
  if (options.extensions != null) args.push('--extensions', String(options.extensions));
  pushFlag(options.failOnError, '--fail-on-error');
  if (options.ignoreConfig) {
    const list = Array.isArray(options.ignoreConfig) ? options.ignoreConfig : [options.ignoreConfig];
    for (const v of list) args.push('--ignore-config', String(v));
  }
  if (options.ignorePattern) {
    const list = Array.isArray(options.ignorePattern) ? options.ignorePattern : [options.ignorePattern];
    for (const v of list) args.push('--ignore-pattern', String(v));
  }
  pushFlag(options.gitignore, '--gitignore');
  if (options.parser != null) args.push('--parser', String(options.parser));
  if (options.parserConfig != null) {
